<!doctype html><html><head><meta name="csrf-token" content="{{ csrf_token() }}"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Certificate verification · GemLab Desk</title><link rel="stylesheet" href="/assets/style.css"></head><body class="verify-body"><main class="verify-wrap"><a class="brand verify-brand" href="/"><div class="brand-mark">G</div><div><b>GemLab Desk</b><small>PUBLIC CERTIFICATE CHECK</small></div></a><div class="verify-card"><div class="verify-icon">✓</div><p class="eyebrow">CERTIFICATE AUTHENTICITY</p><h1>Verify a report</h1><p class="muted">Enter the report number printed on the laboratory report.</p><form id="verifyForm"><input id="reportNo" placeholder="e.g. GTL-00001" required><button class="btn primary full">Verify certificate</button></form><div id="verifyResult"></div></div><p class="verify-note">Independent demonstration system. Not affiliated with or authorised by GTL Jaipur, GJEPC or IIGJ Lab.</p></main><script>const esc=(v)=>String(v??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));const f=document.getElementById('verifyForm');f.addEventListener('submit',async e=>{e.preventDefault();const n=document.getElementById('reportNo').value.trim();const r=document.getElementById('verifyResult');r.innerHTML='<p class="muted">Checking…</p>';try{const x=await fetch('/api/verify/'+encodeURIComponent(n));const d=await x.json();if(!x.ok)throw Error(d.message||'Not found');const a=d.report;r.innerHTML=`<div class="verify-valid"><b>✓ Report found</b><span>Report number: ${esc(a.report_no)}</span><span>Sample: ${esc(a.sample_no)}</span><span>Description: ${esc(a.description)}</span><span>Gemstone: ${esc(a.gemstone_type||'Not specified')}</span><span>Conclusion: ${esc(a.conclusion)}</span><span>Issued: ${esc(a.issued_at)}</span></div>`}catch(err){r.innerHTML=`<div class="alert">${esc(err.message)}</div>`}});const p=new URLSearchParams(location.search).get('report');if(p){document.getElementById('reportNo').value=p;f.requestSubmit()}</script></body></html>
